"""Row data for video 07 (The Pig War). Run: python3 videos/07-varkensoorlog/make_beelden.py -> beelden.json
No chapter cards (Thijs 11-11-2026): the part boundaries get a bridge image. Thread: "whose island is this?"."""
import json, os

E59 = "1859 in the Pacific Northwest"
CUTLAR = ("Lyman Cutlar, an American farmer stickman with a short brown beard, a battered straw hat, a red flannel shirt, "
          "brown trousers and braces")
GRIFFIN = ("Charles Griffin, a British farm manager stickman with grey side-whiskers, a dark green tweed coat, "
           "a waistcoat and a low brown hat")
PICKETT = ("Captain George Pickett, a stickman with long dark curled hair to his shoulders and a mustache, in a dark blue "
           "1850s US Army frock coat with brass buttons and a blue forage cap")
BAYNES = ("Rear Admiral Robert Baynes, an older stickman with white side-whiskers, in a dark navy 1850s Royal Navy coat "
          "with gold epaulettes and a black bicorne hat")
DOUGLAS = ("Governor James Douglas, a tall stern stickman with dark hair and a high white collar, in a black 1850s frock coat")
HARNEY = ("General William Harney, a tall stickman with a white beard, in a dark blue 1850s US Army general's uniform "
          "with gold epaulettes")
SCOTT = ("General Winfield Scott, a big heavy old stickman with white hair, in a dark blue 1850s US Army general's uniform "
         "with gold epaulettes and a yellow sash")
BUCHANAN = ("President James Buchanan, an old stickman with white hair swept up, a very high white collar and a black "
            "1850s frock coat")
KAISER = ("Kaiser Wilhelm I, an old stickman with big white side-whiskers and a white mustache, in a dark blue Prussian "
          "military uniform with a spiked helmet (Pickelhaube)")
USSOLD = "American soldiers of 1859 in dark blue frock coats, light-blue trousers and blue forage caps, with muskets"
MARINES = "British Royal Marines of 1859 in red coats with white cross-belts and dark shakos, with muskets"
USFLAG59 = "the 1850s American flag (stars and stripes)"
UJ = "the British Union Jack"
PIG = "a big black pig with a round friendly face"
RANGER = ("a modern American park ranger stickman in a grey shirt, green trousers and a flat-brimmed ranger hat")
NEIGH = "two modern stickman neighbours (one in a green sweater, one in an orange t-shirt)"
NARR = "a friendly modern stickman narrator in a blue hoodie and jeans"

R = []
_cnt = [0]
TAG = {}
def row(anchor, typ, beeld, era="none", ref=None, tag=None, n=None):
    if n is None:
        _cnt[0] += 1; n = _cnt[0]
    if tag:
        TAG[tag] = str(n)
    R.append({"n": str(n), "anchor": anchor, "type": typ, "beeld": beeld, "era": era, "ref": ref or []})

